import{devices,preset,validate,estimatedWatts}from'./state.js';const q=s=>document.querySelector(s);const key='safonov-room-control-v1';let state=preset('evening'),world;try{const v=localStorage.getItem(key);if(v)state=validate(JSON.parse(v))}catch{}
const names={morning:'Светлое утро',evening:'Тёплый вечер',cinema:'Время кино',away:'Всё выключено',custom:'Ваш сценарий'};q('#devices').innerHTML=devices.map(d=>`<div class="device-row"><span class="device-icon">${d.icon}</span><div class="device-info"><h3>${d.name}</h3><p>${d.type}</p></div><button role="switch" data-device="${d.id}" aria-label="${d.name}" aria-checked="true"><span></span></button></div>`).join('');
function draw(){q('#brightness').value=state.brightness;q('#brightness-value').textContent=state.brightness+'%';q('#temperature').innerHTML=state.temperature+'<span>°C</span>';q('#climate-note').textContent=state.ac?`Установлено ${state.temperature} °C · симуляция`:'Климат выключен · симуляция';q('#ac').setAttribute('aria-checked',state.ac);q('#cooler').disabled=!state.ac||state.temperature<=16;q('#warmer').disabled=!state.ac||state.temperature>=30;q('#watts').textContent=estimatedWatts(state)+' Вт';q('#scene-label').textContent=names[state.scene]||names.custom;document.querySelectorAll('[data-device]').forEach(b=>b.setAttribute('aria-checked',state.lights[b.dataset.device]));document.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.scene===state.scene));world?.update(state);try{localStorage.setItem(key,JSON.stringify(state))}catch{q('.saved-note p').textContent='Сохранение в браузере недоступно. Можно скачать сценарий.'}}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{state=preset(b.dataset.scene);draw()});document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{state.lights[b.dataset.device]=!state.lights[b.dataset.device];state.scene='custom';draw()});q('#brightness').oninput=e=>{state.brightness=Number(e.target.value);state.scene='custom';draw()};q('#ac').onclick=()=>{state.ac=!state.ac;state.scene='custom';draw()};q('#cooler').onclick=()=>{if(state.ac){state.temperature=Math.max(16,state.temperature-1);state.scene='custom';draw()}};q('#warmer').onclick=()=>{if(state.ac){state.temperature=Math.min(30,state.temperature+1);state.scene='custom';draw()}};
function setView(top){world?.view(top);q('#view-top').setAttribute('aria-pressed',top);q('#view-default').setAttribute('aria-pressed',!top)}q('#view-top').onclick=()=>setView(true);q('#view-default').onclick=()=>setView(false);q('#reset-view').onclick=()=>setView(false);q('#reset').onclick=()=>{state=preset('evening');draw();setView(false)};q('#export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify({application:'Room Control',version:1,simulation:true,settings:state,estimatedLightingWatts:estimatedWatts(state)},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='room-control-scene.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);q('#toast').textContent='Сценарий сохранён в JSON';q('#toast').classList.add('show');setTimeout(()=>q('#toast').classList.remove('show'),3000)};
draw();try{const{createRoom}=await import('./room.js');world=createRoom(q('#room'));q('#fallback').hidden=true;q('#fallback').style.display='none';draw();window.addEventListener('resize',()=>world?.resize());window.addEventListener('pagehide',event=>{if(!event.persisted)world?.dispose()})}catch(error){q('#render-status').textContent='3D недоступно. Сценарии и сохранение настроек работают.';q('.room-hint').textContent='Для просмотра комнаты нужен браузер с WebGL';console.error(error)}
